function getMaxLen(nums) {
  let positive = 0;
  let negative = 0;
  let best = 0;

  for (const num of nums) {
    if (num === 0) {
      positive = 0;
      negative = 0;
    } else if (num > 0) {
      positive = positive + 1;
      negative = negative > 0 ? negative + 1 : 0;
    } else {
      const previousPositive = positive;
      positive = negative > 0 ? negative + 1 : 0;
      negative = previousPositive + 1;
    }
    best = Math.max(best, positive);
  }
  return best;
}

