function getMaxLen(nums) {
  let answer = 0;
  for (let start = 0; start < nums.length; start++) {
    let sign = 1;
    for (let end = start; end < nums.length; end++) {
      sign *= Math.sign(nums[end]);
      if (sign === 0) break;
      if (sign > 0) answer = Math.max(answer, end - start + 1);
    }
  }
  return answer;
}

