function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const zeroChance = size === 'large' ? [0, 0.002, 0.01][Math.floor(rand() * 3)] : rand() * 0.3;
  const negativeChance = 0.1 + rand() * 0.8;
  const limit = size === 'large' ? 1e9 : 5;
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (rand() < zeroChance) { nums.push(0); continue; }
    const magnitude = 1 + Math.floor(rand() * limit);
    nums.push(rand() < negativeChance ? -magnitude : magnitude);
  }
  return [nums];
}
